correctedCode:
class Person {
    String name;

    Person(String name) {
        this.name = name;
    }
}

class Employee extends Person {
    double salary;

    Employee(String name, double salary) {
        super(name);
        this.salary = salary;
    }
}

public class Main {
    public static void main(String[] args) {
        Employee e = new Employee("Asha", 50000);
        System.out.println(e.name);
    }
}
